/**
 * The stage evidence after this result, from which `stages` is computed: whether the model and the candidate this result
 * is the answer of exist (B9.4). A preview keeps nothing, so it carries the study's own evidence (B4.5).
 */
export interface StageEvidence {
  /**
   * Tune, Validate and Apply apply to the loop. False for an open-loop experiment or an observation loop (C12), whose
   * project owns the controller: those three stages are Not applicable.
   */
  controllerStagesApply: boolean;
  /**
   * A controller candidate exists.
   */
  hasCandidate: boolean;
  /**
   * The project declares its own analysis.
   */
  hasDeclaredAnalysis: boolean;
  /**
   * Manual controller parameters are entered.
   */
  hasManualParameters: boolean;
  /**
   * A plant model exists.
   */
  hasModel: boolean;
  /**
   * A recording exists.
   */
  hasRecording: boolean;
  /**
   * The last identification failed.
   */
  identificationFailed: boolean;
  /**
   * A loop is bound, so Monitor and Test can be used.
   */
  loopBound: boolean;
  /**
   * Validation has a result.
   */
  validationHasResult: boolean;
  /**
   * That result is inconclusive: a requirement lacks the evidence to pass or to fail (B5.4).
   */
  validationInconclusive: boolean;
  /**
   * That result passed.
   */
  validationPassed: boolean;
  [k: string]: unknown;
}
/**
 * One stage's status, with the words the panel shows. A stage that is Not applicable also names the reason, which the page
 * shows in place of its actions (C12).
 */
export interface StageAvailability {
  /**
   * The status in words.
   */
  label: string;
  /**
   * Why the stage does not apply, when its status is Not applicable.
   */
  reason?: string | null;
  /**
   * The stage.
   */
  stage: "Monitor" | "Test" | "Identify" | "Tune" | "Validate" | "Apply";
  /**
   * Its status.
   */
  status: "ready" | "needs-data" | "in-progress" | "complete" | "warning" | "failed" | "not-applicable";
  [k: string]: unknown;
}
/**
 * What a state-law Tune answers: the family, the closed-loop poles of the candidate, the horizon stages when the design has a
 * finite horizon, and the design-form fields of the family.
 */
export interface StateAnswer {
  /**
   * The closed-loop poles of the candidate's mapped coefficients, on the sampled model (N7.11).
   */
  closedLoopPoles: ComplexValue[];
  /**
   * The family of the design.
   */
  family: "state-feedback" | "LQR" | "LQG";
  /**
   * The fields the design form shows for the family, with their labels (D-B12).
   */
  fields: FormField[];
  /**
   * The finite-horizon stages (the gains and the Riccati matrices), when the design has a finite horizon.
   */
  horizon?: StateHorizon | null;
  [k: string]: unknown;
}
/**
 * A complex number as its real and imaginary parts.
 */
export interface ComplexValue {
  /**
   * The imaginary part.
   */
  imaginary: number;
  /**
   * The real part.
   */
  real: number;
  [k: string]: unknown;
}
/**
 * One field of the design form that a family shows, with the label the page shows for it (the page's words, see `draft_label`).
 */
export interface FormField {
  /**
   * The field.
   */
  field:
    | "desiredPoles"
    | "stateWeights"
    | "inputWeights"
    | "processNoise"
    | "measurementNoise"
    | "solverMode"
    | "horizonSteps"
    | "terminalWeights";
  /**
   * The label the form shows.
   */
  label: string;
  [k: string]: unknown;
}
/**
 * The stages of a finite-horizon design.
 */
export interface StateHorizon {
  /**
   * The gains `K_0 … K_{N−1}`.
   */
  gainSequence: number[][][];
  /**
   * The policy that runs the design.
   */
  policy: "repeat-first-finite-gain" | "pinned-fixed-gain";
  /**
   * The Riccati matrices `P_0 … P_N`.
   */
  riccatiSequence: number[][][];
  /**
   * The number of control steps.
   */
  steps: number;
  [k: string]: unknown;
}
